import socketSERVER_ADDRESS = ("127.0.0.1", 8081)print("Creating socket...")server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)print("Binding...")server_socket.bind(SERVER_ADDRESS)print("Listening...")server_socket.listen(2)print("Waiting for client...")client_socket, client_address = server_socket.accept()print("Client connected!")while True:    client_socket, client_address = server_socket.accept()    client_socket.send(...)    while True:        socket_data = client_socket.recv(1024).decode()        if socket_data.lower() == "exit" or socket_data == "":            client_socket.send("end of conversation.".encode())            break        client_socket.send(socket_data.encode())    client_socket.close()